<x-hris.table id="idp-table" endpoint="/idp/data" :columns="[['key'=>'employee.name','label'=>'Employee'],['key'=>'plan_year','label'=>'Plan year'],['key'=>'coverage_years','label'=>'Coverage'],['key'=>'status','label'=>'Status']]" :actions="[['name'=>'details','label'=>'Details'],['name'=>'edit','label'=>'Edit','when'=>'can_edit'],['name'=>'submit','label'=>'Submit','when'=>'can_edit'],['name'=>'approve','label'=>'Approve','when'=>'can_approve'],['name'=>'delete','label'=>'Delete','danger'=>true,'when'=>'can_edit']]"/>
<x-hris.modal id="idp-modal" title="Individual development plan"><form id="idp-form" data-endpoint="/idp"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" tabindex="-1"></div><div class="row g-3"><x-hris.field name="plan_year" label="Plan year" type="number" :value="now('Asia/Manila')->year" required/><x-hris.field name="coverage_years_text" label="Coverage years" :value="now('Asia/Manila')->year" help="Comma-separated, up to three years." required/><x-hris.field name="purpose" type="select" :options="[1=>'Current role',2=>'Career development',3=>'Succession preparation',4=>'Other']" required/><x-hris.field name="other_purpose" label="Other purpose"/><div class="col-12"><div class="d-flex justify-content-between align-items-center mb-2"><h3 class="h6 mb-0">Development items</h3><button id="add-idp-item" type="button" class="btn btn-sm btn-outline-primary">Add item</button></div><div id="idp-items" class="vstack gap-2"></div></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save draft</button></div></form></x-hris.modal>
@endsection
@push('scripts')<script>document.addEventListener('hris:ready',()=>{const table=document.querySelector('#idp-table'),form=document.querySelector('#idp-form'),list=document.querySelector('#idp-items'),modal=document.querySelector('#idp-modal'),requirements=@json($requirements->map(fn($item)=>['id'=>$item->id,'title'=>$item->title])->values());let editing=false;function addItem(item={}){const row=document.createElement('div');row.className='border rounded p-3 row g-2';row.dataset.id=item.id||'';const select=document.createElement('select');select.className='form-select';select.dataset.requirement=true;select.ariaLabel='Position requirement';select.append(new Option('Employee-proposed / no matrix requirement',''),...requirements.map(x=>new Option(x.title,x.id)));select.value=item.training_requirement_id||'';const proposal=document.createElement('input');proposal.className='form-control';proposal.placeholder='Development proposal';proposal.ariaLabel='Development proposal';proposal.value=item.proposal||'';proposal.required=true;proposal.dataset.proposal=true;const title=document.createElement('input');title.className='form-control';title.placeholder='Training / intervention title';title.ariaLabel='Training or intervention title';title.value=item.title||'';title.required=true;title.dataset.title=true;const remove=document.createElement('button');remove.type='button';remove.className='btn btn-sm btn-outline-danger';remove.textContent='Remove';remove.onclick=()=>{if(list.children.length>1)row.remove()};[select,proposal,title].forEach(control=>{const col=document.createElement('div');col.className='col-md-4';col.append(control);row.append(col)});const actions=document.createElement('div');actions.className='col-12';actions.append(remove);row.append(actions);list.append(row)}function resetItems(items=[{}]){list.replaceChildren();items.forEach(addItem)}document.querySelector('#add-idp-item').onclick=()=>addItem();modal.addEventListener('show.bs.modal',()=>{if(!editing){HRIS.fillForm(form,{plan_year:new Date().getFullYear(),coverage_years_text:new Date().getFullYear(),purpose:1});form.dataset.endpoint='/idp';form.dataset.method='POST';resetItems()}});modal.addEventListener('hidden.bs.modal',()=>{editing=false});HRIS.bindForm(form,{prepare:b=>{b.coverage_years=String(b.coverage_years_text).split(',').map(x=>Number(x.trim())).filter(Boolean);b.items=[...list.children].map(row=>({...(row.dataset.id?{id:Number(row.dataset.id)}:{}),training_requirement_id:row.querySelector('[data-requirement]').value?Number(row.querySelector('[data-requirement]').value):null,proposal:row.querySelector('[data-proposal]').value,title:row.querySelector('[data-title]').value}));delete b.coverage_years_text},success:()=>table.table.load()});table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='details'){HRIS.showDetails('Individual development plan',row);return}if(action==='edit'){editing=true;HRIS.fillForm(form,{...row,coverage_years_text:row.coverage_years.join(', ')});resetItems(row.items);form.dataset.endpoint=`/idp/${row.id}`;form.dataset.method='PUT';HRIS.openModal('idp-modal');return}const verb=action==='delete'?'DELETE':'POST',suffix=action==='delete'?'':`/${action}`;if(await HRIS.confirm(`${action} this development plan?`)){HRIS.feedback((await HRIS.request(`/idp/${row.id}${suffix}`,{method:verb})).message);table.table.load()}}catch(e){HRIS.feedback(e.message,true)}})});</script>@endpush
